LM.LAB = {"cases":[{"id":"nominative","name":"Mianownik","nameEn":"Nominative","questions":"kto? co?","level":"A1","summary":"The dictionary form: the subject of the sentence, and the noun after to jest / to są.","uses":[{"label":"Subject","pl":"Anna pracuje w banku.","en":"Anna works at a bank."},{"label":"After to jest / to są","pl":"To jest mój brat.","en":"This is my brother."},{"label":"Adjective after być","pl":"Kawa jest gorąca.","en":"The coffee is hot."},{"label":"Name after nazywać się","pl":"Nazywam się Tomek.","en":"My name is Tomek."}],"triggers":{"prepositions":[],"verbs":["być + adjective","nazywać się"],"other":["to jest","to są"]},"endings":{"singular":{"masculine":"— (consonant); a few in -a: tata, kolega","feminine":"-a (a few: -i pani, consonant noc)","neuter":"-o / -e / -ę / -um"},"plural":{"masculine personal":"-i / -y / -owie","other":"-y / -i / -e / -a"},"adjective":{"singular":{"masculine":"-y / -i","feminine":"-a","neuter":"-e"},"plural":{"masculine personal":"-i / -y","other":"-e"}}},"traps":["After być a noun goes into the instrumental: Jestem studentem, not Jestem student. With to jest the noun stays in the nominative: To jest student.","Masculine personal plurals change the last consonant: student → studenci, Polak → Polacy. Not studenty, Polaki."],"contrasts":[{"with":"accusative","rule":"The subject is in the nominative. The direct object is in the accusative: feminine nouns change -a to -ę.","examples":["Kawa jest dobra.","Lubię kawę."]}],"topicIds":["a1-cases-nominative","a2-cases-nominative-plural"],"setTags":["nominative"]},{"id":"genitive","name":"Dopełniacz","nameEn":"Genitive","questions":"kogo? czego?","level":"A1","summary":"Absence, possession, quantity, and after many prepositions.","uses":[{"label":"After negation","pl":"Nie mam czasu.","en":"I don't have time."},{"label":"Possession (of whom?)","pl":"To jest samochód Marka.","en":"This is Marek's car."},{"label":"Quantity and containers","pl":"Poproszę butelkę wody.","en":"A bottle of water, please."},{"label":"After do, z, bez, dla, u","pl":"Idę do sklepu.","en":"I'm going to the shop."}],"triggers":{"prepositions":["do","z (from)","od","bez","dla","u","obok","koło"],"verbs":["szukać","słuchać","używać","bać się","potrzebować"],"other":["nie ma","nie mam, nie lubię …","dużo","mało","kilka","pięć i więcej"]},"endings":{"singular":{"masculine":"-a / -u","feminine":"-y / -i","neuter":"-a"},"plural":{"masculine personal":"-ów / -i / -y","other":"-ów / — / -i / -y"},"adjective":{"singular":{"masculine":"-ego","feminine":"-ej","neuter":"-ego"},"plural":{"masculine personal":"-ych / -ich","other":"-ych / -ich"}}},"traps":["English does not change the object after not, so learners keep the accusative: Nie mam czas ✗ → Nie mam czasu ✓.","Masculine people and animals that end in a consonant always take -a (brata, kota). For things it is -a or -u, and you learn them in pairs (dom – domu, chleb – chleba).","After nie only an object that would be in the accusative changes. The subject stays in the nominative (Kawa nie jest droga), and other cases stay too (Nie pomagam mamie)."],"contrasts":[{"with":"accusative","rule":"A positive sentence takes the accusative. The same sentence with nie takes the genitive.","examples":["Mam samochód.","Nie mam samochodu."]},{"with":"locative","rule":"do + genitive = where to (a shop, a city). w + locative = where you are.","examples":["Jadę do Krakowa.","Mieszkam w Krakowie."]}],"topicIds":["a1-cases-genitive-basics","a2-cases-genitive-plural-quantities"],"setTags":["genitive"]},{"id":"accusative","name":"Biernik","nameEn":"Accusative","questions":"kogo? co?","level":"A1","summary":"The direct object: the person or thing the action goes to.","uses":[{"label":"Direct object","pl":"Czytam książkę.","en":"I'm reading a book."},{"label":"Ordering","pl":"Poproszę kawę.","en":"A coffee, please."},{"label":"Where to, after na","pl":"Idę na koncert.","en":"I'm going to a concert."},{"label":"Days of the week","pl":"w sobotę","en":"on Saturday"}],"triggers":{"prepositions":["na (where to)","w (days: w sobotę)","przez","za (in … time)","o (prosić o, pytać o)"],"verbs":["mieć","lubić","znać","widzieć","czytać","pić","jeść","kupować","kochać","odwiedzać"],"other":[]},"endings":{"singular":{"masculine (people, animals)":"-a (in -a: tata → tatę)","masculine (things)":"= nominative","feminine":"-ę (pani → panią, noc → noc)","neuter":"= nominative"},"plural":{"masculine personal":"= genitive","other":"= nominative"},"adjective":{"singular":{"masculine (people, animals)":"-ego","masculine (things)":"-y / -i","feminine":"-ą","neuter":"-e"},"plural":{"masculine personal":"-ych / -ich","other":"-e"}}},"traps":["English marks the object only by its place in the sentence. Polish needs the ending: Lubię kawę, not Lubię kawa.","Masculine people and animals take -a, like the genitive: Mam brata, Mam psa. Things do not change: Mam dom.","After nie the object switches to the genitive: Mam czas. → Nie mam czasu.","Going into a building or a town takes do + genitive, not w + accusative: Idę do szkoły, not Idę w szkołę."],"contrasts":[{"with":"genitive","rule":"Positive sentence: accusative. Negated sentence: genitive.","examples":["Mam samochód.","Nie mam samochodu."]},{"with":"nominative","rule":"A feminine noun ends in -a as the subject and in -ę as the object.","examples":["Książka jest ciekawa.","Czytam książkę."]},{"with":"locative","rule":"na + accusative = where to. na + locative = where. With w, where to is usually do + genitive: Idę do szkoły, Jestem w szkole.","examples":["Idę na pocztę.","Jestem na poczcie."]}],"topicIds":["a1-cases-accusative","a2-cases-accusative-plural"],"setTags":["accusative"]}],"models":[{"id":"nowy-student","gender":"masculine personal","en":"new student","singular":{"nominative":"nowy student","genitive":"nowego studenta","dative":"nowemu studentowi","accusative":"nowego studenta","instrumental":"nowym studentem","locative":"nowym studencie","vocative":"nowy studencie"},"plural":{"nominative":"nowi studenci","genitive":"nowych studentów","dative":"nowym studentom","accusative":"nowych studentów","instrumental":"nowymi studentami","locative":"nowych studentach","vocative":"nowi studenci"}},{"id":"stary-dom","gender":"masculine inanimate","en":"old house","singular":{"nominative":"stary dom","genitive":"starego domu","dative":"staremu domowi","accusative":"stary dom","instrumental":"starym domem","locative":"starym domu","vocative":"stary domu"},"plural":{"nominative":"stare domy","genitive":"starych domów","dative":"starym domom","accusative":"stare domy","instrumental":"starymi domami","locative":"starych domach","vocative":"stare domy"}},{"id":"dobra-kawa","gender":"feminine","en":"good coffee","note":"In the plural: cups or kinds of coffee (Poproszę dwie kawy).","singular":{"nominative":"dobra kawa","genitive":"dobrej kawy","dative":"dobrej kawie","accusative":"dobrą kawę","instrumental":"dobrą kawą","locative":"dobrej kawie","vocative":"dobra kawo"},"plural":{"nominative":"dobre kawy","genitive":"dobrych kaw","dative":"dobrym kawom","accusative":"dobre kawy","instrumental":"dobrymi kawami","locative":"dobrych kawach","vocative":"dobre kawy"}},{"id":"male-okno","gender":"neuter","en":"small window","singular":{"nominative":"małe okno","genitive":"małego okna","dative":"małemu oknu","accusative":"małe okno","instrumental":"małym oknem","locative":"małym oknie","vocative":"małe okno"},"plural":{"nominative":"małe okna","genitive":"małych okien","dative":"małym oknom","accusative":"małe okna","instrumental":"małymi oknami","locative":"małych oknach","vocative":"małe okna"}}],"trees":[{"id":"pick-case","title":"Pick the case","intro":"Think of one noun in your sentence and answer the questions about it.","start":"start","nodes":{"start":{"question":"Is there a preposition right before the noun (or before its adjective)?","help":"Prepositions are short words such as do, z, w, na, bez, dla, u.","options":[{"label":"Yes, there is a preposition","next":"preposition"},{"label":"No preposition","next":"role"}]},"preposition":{"question":"Which preposition is it?","options":[{"label":"do, od, bez, dla, u, obok, koło","result":["genitive"],"why":"These prepositions always take the genitive.","example":{"pl":"Idę do sklepu.","en":"I'm going to the shop."}},{"label":"z","next":"z"},{"label":"na","next":"na"},{"label":"w","next":"w"},{"label":"przez, or za meaning in … time (za tydzień)","result":["accusative"],"why":"przez and za meaning in … time take the accusative. (za meaning behind takes the instrumental: za domem.)","example":{"pl":"Wracam za tydzień.","en":"I'm coming back in a week."}},{"label":"o, po, przy (about, after, next to)","result":["locative"],"why":"o, po and przy usually take the locative: mówić o filmie, po lekcji, przy oknie. (o meaning for, as in prosić o, takes the accusative, and so does po meaning to fetch: Idę po chleb.)","example":{"pl":"Rozmawiamy o pracy.","en":"We're talking about work."}},{"label":"przed, pod, nad, między (in front of, under, above, between)","result":["instrumental"],"why":"When they say where something is, these prepositions take the instrumental. (Going under or in front of something takes the accusative: Kot wchodzi pod stół.)","example":{"pl":"Czekam przed domem.","en":"I'm waiting in front of the house."}}]},"z":{"question":"What does z mean here?","options":[{"label":"from, out of (Where from?)","result":["genitive"],"why":"z meaning from takes the genitive.","example":{"pl":"Jestem z Polski.","en":"I'm from Poland."}},{"label":"with, together with (With whom? With what?)","result":["instrumental"],"why":"z meaning with takes the instrumental.","example":{"pl":"Piję kawę z mlekiem.","en":"I drink coffee with milk."}}]},"na":{"question":"Does na say where something goes, or where it is?","options":[{"label":"Where it goes (Where to?)","result":["accusative"],"why":"na + accusative = where to.","example":{"pl":"Idę na koncert.","en":"I'm going to a concert."}},{"label":"Where it is (Where?)","result":["locative"],"why":"na + locative = where.","example":{"pl":"Jestem na koncercie.","en":"I'm at a concert."}}]},"w":{"question":"What does w say here?","options":[{"label":"Where something is (Where?)","result":["locative"],"why":"w + locative = where: in a building, a town, a country.","example":{"pl":"Mieszkam w Krakowie.","en":"I live in Kraków."}},{"label":"Where someone goes: into a building, a town, a country","result":["genitive"],"why":"Going into a place usually takes do + genitive, not w: Idę do szkoły, not Idę w szkołę.","example":{"pl":"Jadę do Warszawy.","en":"I'm going to Warsaw."}},{"label":"A day of the week (on Monday …)","result":["accusative"],"why":"w + a day of the week takes the accusative. (Months and years take the locative: w maju.)","example":{"pl":"Do zobaczenia w sobotę.","en":"See you on Saturday."}},{"label":"A month or a year (in May, in 2025)","result":["locative"],"why":"w + a month or a year takes the locative.","example":{"pl":"Mam urlop w maju.","en":"I have a holiday in May."}}]},"role":{"question":"What does the noun do in the sentence?","options":[{"label":"It is the subject: the person or thing that does the action","result":["nominative"],"why":"The subject is in the nominative. (After quantity words like dużo or pięć it goes into the genitive: Pięć osób czeka.)","example":{"pl":"Mój brat pracuje w Warszawie.","en":"My brother works in Warsaw."}},{"label":"It comes after to jest or to są","result":["nominative"],"why":"After to jest / to są the noun stays in the nominative.","example":{"pl":"To jest moja siostra.","en":"This is my sister."}},{"label":"It is a noun after być saying who someone is (a job, a nationality, a role)","result":["instrumental"],"why":"być + noun takes the instrumental: Jestem lekarzem. With a first name in an introduction the nominative is usual: Jestem Tomek. An adjective after być stays in the nominative: Kawa jest gorąca.","example":{"pl":"Ona jest nauczycielką.","en":"She is a teacher."}},{"label":"It is the object of the verb: the person or thing the action goes to","next":"object"},{"label":"It says whose something is, or follows a quantity word (dużo, mało, pięć …)","result":["genitive"],"why":"Possession and quantities take the genitive.","example":{"pl":"Mam dużo pracy.","en":"I have a lot of work."}},{"label":"It is the person who receives something (To whom?)","result":["dative"],"why":"The receiver of a gift, a message or help is in the dative.","example":{"pl":"Daję mamie kwiaty.","en":"I'm giving my mum flowers."}},{"label":"It is a tool or a means of transport (With what? By what?)","result":["instrumental"],"why":"Tools and means of transport without a preposition take the instrumental.","example":{"pl":"Jadę autobusem.","en":"I'm going by bus."}},{"label":"You are speaking to someone directly","result":["vocative"],"why":"Addressing someone takes the vocative.","example":{"pl":"Dzień dobry, panie profesorze!","en":"Good morning, professor!"}}]},"object":{"question":"Which kind of verb is it?","help":"A few verbs take another case for their object. Check them first.","options":[{"label":"szukać, słuchać, potrzebować, używać, bać się","result":["genitive"],"why":"These verbs take the genitive, also in a positive sentence.","example":{"pl":"Szukam klucza.","en":"I'm looking for the key."}},{"label":"pomagać, dziękować, or the person after dawać (komu?)","result":["dative"],"why":"The person you help, thank or give something to is in the dative, also after nie. The thing you give stays in the accusative: Daję mamie kwiaty.","example":{"pl":"Pomagam bratu.","en":"I'm helping my brother."}},{"label":"Another verb (mieć, lubić, kupować, czytać …)","next":"negation"}]},"negation":{"question":"Is the verb negated with nie?","options":[{"label":"Yes, there is nie before the verb","result":["genitive"],"why":"After nie the direct object switches from the accusative to the genitive.","example":{"pl":"Nie lubię kawy.","en":"I don't like coffee."}},{"label":"No, the sentence is positive","result":["accusative"],"why":"Most verbs take a direct object in the accusative.","example":{"pl":"Kupuję gazetę i kawę.","en":"I'm buying a newspaper and coffee."}}]}}}],"aspect":{"title":"Aspect and tense on one timeline","summary":"Most Polish verbs come in pairs. The imperfective verb looks at the action as a process or a habit; the perfective verb looks at one finished result. Together they give five forms.","note":"A perfective verb has no present tense: przeczyta looks like a present form but means the future.","verb":{"imperfective":"czytać","perfective":"przeczytać","en":"to read"},"forms":[{"id":"present","name":"Present","aspect":"imperfective","form":"czyta","summary":"Happening now, or as a habit. Only imperfective verbs have a present tense.","scene":{"label":"Now","description":"The reading is going on at the moment of speaking.","elements":[{"kind":"range","from":-0.2,"to":0.2,"label":"in progress"}]},"example":{"pl":"Ola czyta książkę.","en":"Ola is reading a book."}},{"id":"past-imperfective","name":"Past","aspect":"imperfective","form":"czytała","summary":"A process in the past: how long it went on, or what was happening. It does not say if it was finished.","scene":{"label":"Process in the past","description":"The reading went on for some time yesterday; we do not know if Ola finished the book.","elements":[{"kind":"range","from":-0.85,"to":-0.35,"label":"process"}]},"example":{"pl":"Wczoraj Ola czytała książkę przez dwie godziny.","en":"Yesterday Ola spent two hours reading a book."}},{"id":"past-perfective","name":"Past","aspect":"perfective","form":"przeczytała","summary":"One finished action with a result: the whole book is read.","scene":{"label":"Result in the past","description":"At one point in the past the reading was finished; the result is there.","elements":[{"kind":"result","at":-0.45,"label":"done"}]},"example":{"pl":"Ola już przeczytała tę książkę.","en":"Ola has already read this book."}},{"id":"future-imperfective","name":"Future","aspect":"imperfective","form":"będzie czytać","summary":"A process in the future: będzie + the infinitive (or + the past-tense form that agrees with the subject: będzie czytała / będzie czytał).","scene":{"label":"Process in the future","description":"Tomorrow evening the reading will go on for some time.","elements":[{"kind":"range","from":0.35,"to":0.85,"label":"process"}]},"example":{"pl":"Jutro Ola będzie czytać cały wieczór.","en":"Tomorrow Ola will be reading all evening."}},{"id":"future-perfective","name":"Future","aspect":"perfective","form":"przeczyta","summary":"One finished result in the future, formed like a present tense.","scene":{"label":"Result in the future","description":"By Friday the reading will be finished.","elements":[{"kind":"result","at":0.6,"label":"done"}]},"example":{"pl":"Ola przeczyta tę książkę do piątku.","en":"Ola will have read this book by Friday."}}]}};
